// Capture each completed run before the player can start the next stage.
const scoreUiSession=Date.now()+':'+Math.random();let scoreOutbox=[];const scoreTasks=new Set();let scoreFlushBusy=false;
try{scoreOutbox=JSON.parse(localStorage.getItem('hammy-score-outbox')||'[]').filter(e=>e&&typeof e.token==='string'&&Date.now()-e.queuedAt<3600000)}catch{}
function storeOutbox(){try{localStorage.setItem('hammy-score-outbox',JSON.stringify(scoreOutbox))}catch{}}
function scoreStatus(serial,message,session=scoreUiSession){if(session===scoreUiSession&&runSerial===serial&&state==='won')$('scoreStatus').textContent=message;}
async function queueAutomaticScore(score,sessionPromise,serial){
 if(scoreTasks.has(serial))return;scoreTasks.add(serial);scoreStatus(serial,'Saving your score online automatically...');
 try{const session=await sessionPromise;if(!session?.token)throw Error('Saved on this device. This run was not connected online.');const entry={...score,token:session.token,serial,uiSession:scoreUiSession,queuedAt:Date.now(),attempts:0};if(!scoreOutbox.some(e=>e.token===entry.token)){scoreOutbox.push(entry);storeOutbox()}await flushScores();}
 catch(e){scoreStatus(serial,e.message)}
}
async function flushScores(){
 if(scoreFlushBusy||location.protocol==='file:'||navigator.onLine===false)return;scoreFlushBusy=true;
 try{for(const entry of [...scoreOutbox]){
 if(Date.now()-entry.queuedAt>=3600000){scoreOutbox=scoreOutbox.filter(e=>e.token!==entry.token);storeOutbox();continue}
 try{await api('/api/score',{method:'POST',body:JSON.stringify({level:entry.level,time_ms:entry.time_ms,crystals:entry.crystals,version:entry.version,token:entry.token})});scoreOutbox=scoreOutbox.filter(e=>e.token!==entry.token);storeOutbox();scoreStatus(entry.serial,'Score saved online automatically',entry.uiSession);if($('leaderboardDialog').open)fetchBoard();}
 catch(e){entry.attempts++;if([400,403,404,409].includes(e.status)){scoreOutbox=scoreOutbox.filter(e=>e.token!==entry.token);scoreStatus(entry.serial,'Saved on this device - '+e.message,entry.uiSession)}else{scoreStatus(entry.serial,'Saved on this device. Your score will upload when connected.',entry.uiSession);if(entry.attempts<=3)setTimeout(flushScores,Math.min(30000,entry.attempts*3000))}storeOutbox();}
 }}finally{scoreFlushBusy=false;if(scoreOutbox.some(e=>e.attempts===0))setTimeout(flushScores,0)}
}
window.addEventListener('online',flushScores);setTimeout(flushScores,500);
setInterval(()=>{if(!document.hidden&&$('leaderboardDialog').open)fetchBoard()},20000);

setInterval(()=>{if(scoreOutbox.length)flushScores()},30000);

// User-supplied FBX/DAE meshes, converted to compact buffers with 512px albedo maps.
const importedModels=new Map();let chevronMesh=null;
function decodeAsset(base64,Type){const binary=atob(base64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new Type(bytes.buffer)}
function getImportedModel(name){if(importedModels.has(name))return importedModels.get(name);const data=window.HAMMY_MODELS?.[name];if(!data)return null;const textures=data.textures.map(uri=>{const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1,1,0,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array([220,220,220,255]));gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);const image=new Image();image.onload=()=>{gl.bindTexture(gl.TEXTURE_2D,texture);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,image);gl.generateMipmap(gl.TEXTURE_2D);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR_MIPMAP_LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR)};image.src=uri;return texture});const parts=data.parts.map(part=>{const input=decodeAsset(part.vertices,Float32Array),indices=decodeAsset(part.indices,Uint16Array),vertices=new Float32Array(indices.length*12);for(let i=0;i<indices.length;i++){const src=indices[i]*8,dst=i*12;vertices.set(input.subarray(src,src+6),dst);vertices.set([1,1,1],dst+6);vertices.set(input.subarray(src+6,src+8),dst+9);vertices[dst+11]=0}return{...part,mesh:mesh(vertices)}});const model={...data,parts,textures};importedModels.set(name,model);return model}
function drawImported(name,parent,options={}){const asset=getImportedModel(name);if(!asset)return false;asset.parts.forEach((part,index)=>{if(options.part!=null&&index!==options.part)return;let matrix=parent;if(part.part==='rotor'){const pivot=asset.pivot;matrix=multiply(parent,multiply(model(...pivot),transform3(0,0,0,1,1,1,0,0,-propClock*10)))}drawMesh(part.mesh,matrix,[1,1,1],1,asset.textures[part.texture])});return true}
function rampHeight(p,x,z){const hf=window.HAMMY_MODELS?.ramp?.heightfield;if(!hf||p.type!=='spring')return 0;const q=pointOn(p,.78),dx=x-q.x,dz=z-q.z,lx=dx*p.uz-dz*p.ux,lz=dx*p.ux+dz*p.uz;if(lx<hf.minX||lx>hf.maxX||lz<hf.minZ||lz>hf.maxZ)return 0;const fx=(lx-hf.minX)/(hf.maxX-hf.minX)*(hf.nx-1),fz=(lz-hf.minZ)/(hf.maxZ-hf.minZ)*(hf.nz-1),ix=Math.min(hf.nx-2,Math.floor(fx)),iz=Math.min(hf.nz-2,Math.floor(fz)),tx=fx-ix,tz=fz-iz;const h=(a,b)=>hf.values[b*hf.nx+a];return (h(ix,iz)*(1-tx)+h(ix+1,iz)*tx)*(1-tz)+(h(ix,iz+1)*(1-tx)+h(ix+1,iz+1)*tx)*tz}
function bumpHeight(p,x,z){if(p.type!=='slow')return 0;const q=pointOn(p,.53),dx=x-q.x,dz=z-q.z,lx=dx*p.uz-dz*p.ux,lz=dx*p.ux+dz*p.uz;return Math.abs(lx)<1.52&&Math.abs(lz)<.40?.086*Math.cos(lz/.4*Math.PI/2):0}
function drawAssetPad(p){const q=pointOn(p,p.type==='spring'?.78:.53),yaw=Math.atan2(p.ux,p.uz);
 if(p.type==='slow'){for(let i=0;i<8;i++){const side=(i-3.5)*.38,pos=pointOn(p,.53,side);drawImported('bump',model(pos.x,pos.y+.005,pos.z,1,1,1,yaw),{part:i%2})}return}
 if(p.type==='spring'){drawImported('ramp',model(q.x,q.y+.005,q.z,1,1,1,yaw));return}
 if(p.type==='boost'){drawBoost(p);return}
}

function drawSpikeTrap(o){const side=o.side+Math.sin(elapsed*1.7+o.phase)*o.amp,x=o.x+o.p.uz*side,z=o.z-o.p.ux*side;drawImported('spikes',model(x,o.y+.006,z,1,1,1,Math.atan2(o.p.ux,o.p.uz)))}
function drawFan(f){const d=fanDirection(f),yaw=Math.atan2(d.x,d.z),height=window.HAMMY_MODELS?.fan?.pivot?.[1]||1.12;drawMesh(cubeMesh,model(f.x+d.x*.27,f.y-.08,f.z+d.z*.27,.45,.14,.9,yaw),[.20,.30,.32]);drawImported('fan',model(f.x,f.y,f.z,1,1,1,yaw));const right=[d.z,-d.x];gl.depthMask(false);for(let i=0;i<16;i++){const distance=(propClock*4+i*.31)%4.8+.55,spread=Math.sin(i*9)*(.25+distance*.07),up=Math.cos(i*7)*.28,x=f.x+d.x*distance+right[0]*spread,z=f.z+d.z*distance+right[1]*spread;drawMesh(sphereMesh,model(x,f.y+height+up,z,.045,.035,.28+.03*distance,yaw),[.76,.96,1],.55*(1-distance/6))}gl.depthMask(true)}
function makeChevron(){const out=[],points=[[-.9,0,-.3],[0,0,.15],[.9,0,-.3],[.9,0,.08],[0,0,.53],[-.9,0,.08]],upper=points.map(p=>[p[0],.075,p[2]]);for(const indices of [[0,1,4,5],[1,2,3,4]])quad(out,...indices.map(i=>upper[i]),[.15,1,.28]);for(let i=0;i<6;i++){const next=(i+1)%6;quad(out,points[i],upper[i],upper[next],points[next],[.04,.52,.14])}return mesh(out)}
function boostDirection(p){const angle=Math.atan2(p.ux,p.uz)+(p.boostTurn||0);return{x:Math.sin(angle),z:Math.cos(angle),angle}}
function drawBoost(p){if(!chevronMesh)chevronMesh=makeChevron();const q=pointOn(p,.53),d=boostDirection(p),yaw=d.angle;drawMesh(cubeMesh,model(q.x,q.y+.025,q.z,2.25,.07,2.5,yaw),[.28,.37,.38]);for(let i=0;i<5;i++){const dist=(i-2)*.48,x=q.x+d.x*dist,z=q.z+d.z*dist,y=p.y-p.drop*coords(p,x,z).t;drawMesh(chevronMesh,model(x,y+.065,z,1,1,.58,yaw),[1,1,1],1,null,1);gl.depthMask(false);drawMesh(chevronMesh,model(x,y+.075,z,1.06,.18,.64,yaw),[.15,1,.32],.12+.08*Math.sin(propClock*5-i),null,1);gl.depthMask(true)}}
function wreckingPosition(o){const angle=Math.sin(elapsed*1.12+o.phase)*.65,side=Math.sin(angle)*3.1;return{x:o.x+o.p.uz*side,y:o.y+3.7-Math.cos(angle)*3.1,z:o.z-o.p.ux*side,angle}}
function drawWrecker(o){const pos=wreckingPosition(o),yaw=Math.atan2(o.p.ux,o.p.uz),pivot=[o.x,o.y+3.7,o.z];for(const side of [-1,1]){const q=pointOn(o.p,.5,side*(o.p.width/2+.18));drawMesh(cubeMesh,model(q.x,q.y+1.85,q.z,.14,3.7,.18,yaw),[.24,.28,.29]);}drawMesh(cubeMesh,model(o.x,o.y+3.7,o.z,o.p.width+.5,.20,.22,yaw),[.75,.52,.20]);
 const chain=sub([pos.x,pos.y+.48,pos.z],pivot);for(let i=0;i<13;i++){const t=(i+.5)/13,q=pivot.map((v,k)=>v+chain[k]*t);drawMesh(torusMesh,transform3(...q,.075,.12,.075,yaw,Math.PI/2,i%2?Math.PI/2:0),[.20,.23,.24]);}sphere(pos.x,pos.y,pos.z,.59,.59,.59,[.17,.20,.21]);drawMesh(torusMesh,transform3(pos.x,pos.y,pos.z,.585,.40,.585,propClock*.08,Math.PI/2),[.26,.29,.28]);sphere(pos.x-.14,pos.y+.23,pos.z-.40,.13,.05,.06,[.39,.43,.40],.42)}
